import express from 'express';
import {asyncHandler} from '../../shared/http/async-handler';
import {ok,page} from '../../shared/http/respond';
import {bodyObject,requireEnum,requireString,optionalString,pick,requireUuid} from '../../shared/http/validate';
import {query,transaction} from '../../shared/db/database';
import {requireActive,requirePermission} from '../../middleware/auth';
import {AppError} from '../../shared/errors/app-error';
import {audit,outbox} from '../../shared/domain/audit';
import {uploadIntent,assertMedia,signS3Url} from '../../shared/providers/media';

export const vendorRouter=express.Router();
async function ownApplication(id:string,accountId:string,forUpdate=false,tx:any={query}){const r=await tx.query(`SELECT va.*,v.account_id,v.vendor_type,v.status vendor_status,v.public_display_name FROM vendor_applications va JOIN vendors v ON v.id=va.vendor_id WHERE va.id=$1 AND v.account_id=$2 ${forUpdate?'FOR UPDATE OF va,v':''}`,[id,accountId]);if(!r.rows[0])throw new AppError(404,'VENDOR_APPLICATION_NOT_FOUND','Vendor application not found.');return r.rows[0];}
async function adminApplication(id:string,tx:any={query},forUpdate=false){const r=await tx.query(`SELECT va.*,v.account_id,v.vendor_type,v.status vendor_status FROM vendor_applications va JOIN vendors v ON v.id=va.vendor_id WHERE va.id=$1 ${forUpdate?'FOR UPDATE OF va,v':''}`,[id]);if(!r.rows[0])throw new AppError(404,'VENDOR_APPLICATION_NOT_FOUND','Vendor application not found.');return r.rows[0];}
async function statusHistory(tx:any,appId:string,from:string|null,to:string,actor:string|null,reason:string|null){await tx.query(`INSERT INTO vendor_application_status_history(vendor_application_id,from_status,to_status,changed_by_account_id,reason) VALUES($1,$2,$3,$4,$5)`,[appId,from,to,actor,reason]);}

// AC-02 — Vendor Registration & Verification
vendorRouter.post('/vendor-applications',requireActive,asyncHandler(async(req,res)=>{const b=bodyObject(req.body);const type=requireEnum(b,'vendor_type',['INDIVIDUAL','BUSINESS']);const display=optionalString(b,'public_display_name',180)??req.account.displayName;const result=await transaction(async tx=>{const existing=await tx.query(`SELECT id FROM vendors WHERE account_id=$1`,[req.account.id]);if(existing.rows[0])throw new AppError(409,'VENDOR_ALREADY_EXISTS','Account already has a vendor identity.');const v=await tx.query(`INSERT INTO vendors(account_id,vendor_type,public_display_name,business_name) VALUES($1,$2,$3,$4) RETURNING *`,[req.account.id,type,display,type==='BUSINESS'?display:null]);const a=await tx.query(`INSERT INTO vendor_applications(vendor_id) VALUES($1) RETURNING *`,[v.rows[0].id]);await statusHistory(tx,a.rows[0].id,null,'DRAFT',req.account.id,'APPLICATION_CREATED');await audit(tx,{actorId:req.account.id,action:'VENDOR_APPLICATION_CREATED',targetType:'VENDOR_APPLICATION',targetId:a.rows[0].id});return {vendor:v.rows[0],application:a.rows[0]};});ok(res,result,201);}));
vendorRouter.get('/vendors/me',requireActive,asyncHandler(async(req,res)=>{const r=await query<any>(`SELECT * FROM vendors WHERE account_id=$1`,[req.account.id]);if(!r.rows[0])throw new AppError(404,'VENDOR_NOT_FOUND','Vendor not found.');ok(res,r.rows[0]);}));
vendorRouter.get('/vendor-applications/me',requireActive,asyncHandler(async(req,res)=>{const r=await query<any>(`SELECT va.* FROM vendor_applications va JOIN vendors v ON v.id=va.vendor_id WHERE v.account_id=$1 ORDER BY va.created_at DESC LIMIT 1`,[req.account.id]);if(!r.rows[0])throw new AppError(404,'VENDOR_APPLICATION_NOT_FOUND','Vendor application not found.');ok(res,r.rows[0]);}));
vendorRouter.get('/vendor-applications/:id',requireActive,asyncHandler(async(req,res)=>{ok(res,await ownApplication(requireUuid(req.params.id),req.account.id));}));
vendorRouter.patch('/vendor-applications/:id',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);const b=pick(bodyObject(req.body),['declared_identity_name','business_name','representative_name']);const keys=Object.keys(b);if(!keys.length)throw new AppError(400,'VALIDATION_ERROR','No editable field provided.');const result=await transaction(async tx=>{const app=await ownApplication(id,req.account.id,true,tx);if(!['DRAFT','NEEDS_REVISION'].includes(app.status))throw new AppError(409,'VENDOR_APPLICATION_NOT_EDITABLE','Application can only be edited in DRAFT or NEEDS_REVISION.');const sets=keys.map((k,i)=>`${k}=$${i+2}`).join(',');const r=await tx.query(`UPDATE vendor_applications SET ${sets},updated_at=now() WHERE id=$1 RETURNING *`,[id,...keys.map(k=>b[k])]);return r.rows[0];});ok(res,result);}));
vendorRouter.post('/vendor-applications/:id/terms/accept',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);const ver=requireString(bodyObject(req.body),'terms_version',1,80);const r=await transaction(async tx=>{const app=await ownApplication(id,req.account.id,true,tx);if(!['DRAFT','NEEDS_REVISION'].includes(app.status))throw new AppError(409,'VENDOR_APPLICATION_NOT_EDITABLE','Application is not editable.');return (await tx.query(`UPDATE vendor_applications SET terms_version=$2,terms_accepted_at=now(),updated_at=now() WHERE id=$1 RETURNING *`,[id,ver])).rows[0];});ok(res,r);}));
vendorRouter.post('/vendor-applications/:id/documents/upload-intent',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);await ownApplication(id,req.account.id);const b=bodyObject(req.body);const ct=requireString(b,'content_type',1,120);const fn=optionalString(b,'file_name',255);ok(res,{...(await uploadIntent({accountId:req.account.id,dataClass:'VERIFICATION_SENSITIVE',contentType:ct,fileName:fn}))},201);}));
vendorRouter.post('/vendor-applications/:id/documents',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);const b=bodyObject(req.body);const type=requireEnum(b,'document_type',['KTP','VERIFICATION_SELFIE','NIB_BUSINESS_EVIDENCE','PROFESSIONAL_CREDENTIAL','PORTFOLIO']);const media=requireUuid(b.media_object_id,'media_object_id');await assertMedia(media,req.account.id,'VERIFICATION_SENSITIVE');const r=await transaction(async tx=>{const app=await ownApplication(id,req.account.id,true,tx);if(!['DRAFT','NEEDS_REVISION'].includes(app.status))throw new AppError(409,'VENDOR_APPLICATION_NOT_EDITABLE','Application is not editable.');return (await tx.query(`INSERT INTO vendor_verification_documents(vendor_application_id,document_type,media_object_id) VALUES($1,$2,$3) RETURNING id,document_type,status,created_at`,[id,type,media])).rows[0];});ok(res,r,201);}));
vendorRouter.get('/vendor-applications/:id/documents',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);await ownApplication(id,req.account.id);const r=await query<any>(`SELECT id,document_type,status,review_reason,verified_at,created_at,updated_at FROM vendor_verification_documents WHERE vendor_application_id=$1 ORDER BY created_at`,[id]);ok(res,{items:r.rows});}));
vendorRouter.post('/vendor-applications/:id/submit',requireActive,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);const r=await transaction(async tx=>{const app=await ownApplication(id,req.account.id,true,tx);if(!['DRAFT','NEEDS_REVISION'].includes(app.status))throw new AppError(409,'VENDOR_APPLICATION_NOT_SUBMITTABLE','Application is not submitable from current state.');if(!app.terms_accepted_at)throw new AppError(422,'VENDOR_APPLICATION_INCOMPLETE','Vendor terms must be accepted.');const docs=await tx.query(`SELECT document_type,count(*) n FROM vendor_verification_documents WHERE vendor_application_id=$1 AND status IN ('SUBMITTED','VERIFIED') GROUP BY document_type`,[id]);const have=new Set(docs.rows.map((x:any)=>x.document_type));const required=app.vendor_type==='BUSINESS'?['KTP','VERIFICATION_SELFIE','NIB_BUSINESS_EVIDENCE']:['KTP','VERIFICATION_SELFIE'];const missing=required.filter(x=>!have.has(x));const loc=await tx.query(`SELECT location_type FROM vendor_locations WHERE vendor_id=$1`,[app.vendor_id]);const locTypes=new Set(loc.rows.map((x:any)=>x.location_type));const locationComplete=app.vendor_type==='BUSINESS'?(locTypes.has('VERIFICATION_PRIVATE')&&locTypes.has('PUBLIC_BUSINESS')):(locTypes.has('VERIFICATION_PRIVATE')&&locTypes.has('OPERATIONAL_PRIVATE'));const svc=await tx.query(`SELECT s.id FROM vendor_services s WHERE s.vendor_id=$1 AND EXISTS(SELECT 1 FROM service_packages p WHERE p.vendor_service_id=s.id) AND EXISTS(SELECT 1 FROM vendor_service_pet_rules r WHERE r.vendor_service_id=s.id) AND EXISTS(SELECT 1 FROM service_availability_windows w WHERE w.vendor_service_id=s.id) AND (s.delivery_mode='AT_VENDOR' OR (s.delivery_mode='AT_CUSTOMER' AND s.origin_vendor_location_id IS NOT NULL AND s.service_radius_meters>0)) LIMIT 1`,[app.vendor_id]);const payout=await tx.query(`SELECT 1 FROM vendor_payout_accounts WHERE vendor_id=$1 AND is_active=true LIMIT 1`,[app.vendor_id]);if(missing.length||!locationComplete||!svc.rows[0]||!payout.rows[0])throw new AppError(422,'VENDOR_APPLICATION_INCOMPLETE','Vendor application evidence is incomplete.',{missing_documents:missing,location_complete:locationComplete,service_config_complete:!!svc.rows[0],payout_account:!!payout.rows[0]});const next=(await tx.query(`UPDATE vendor_applications SET status='SUBMITTED',submitted_at=now(),reviewed_by_account_id=NULL,review_started_at=NULL,decision_reason=NULL,decided_at=NULL,updated_at=now() WHERE id=$1 RETURNING *`,[id])).rows[0];await statusHistory(tx,id,app.status,'SUBMITTED',req.account.id,'APPLICATION_SUBMITTED');await outbox(tx,`vendor-application:${id}:submitted:${Date.now()}`,'VENDOR_APPLICATION',id,'VENDOR_APPLICATION_SUBMITTED',{});return next;});ok(res,r);}));

const review=requirePermission('operations.vendor_application.review');
vendorRouter.get('/admin/vendor-applications',requireActive,review,asyncHandler(async(req,res)=>{const p=Number(req.query.page??1)||1,l=Math.min(100,Number(req.query.limit??20)||20),off=(p-1)*l;const status=typeof req.query.status==='string'?req.query.status:null;const [a,c]=await Promise.all([query<any>(`SELECT va.*,v.vendor_type,v.public_display_name,v.status vendor_status FROM vendor_applications va JOIN vendors v ON v.id=va.vendor_id WHERE ($1::text IS NULL OR va.status::text=$1) ORDER BY va.created_at DESC LIMIT $2 OFFSET $3`,[status,l,off]),query<any>(`SELECT count(*)::int total FROM vendor_applications WHERE ($1::text IS NULL OR status::text=$1)`,[status])]);page(res,a.rows,p,l,c.rows[0].total);}));
vendorRouter.post('/admin/vendor-applications/:id/review/start',requireActive,review,asyncHandler(async(req,res)=>{const id=requireUuid(req.params.id);const result=await transaction(async tx=>{const app=await adminApplication(id,tx,true);if(app.status!=='SUBMITTED')throw new AppError(409,'INVALID_STATE_TRANSITION','Only SUBMITTED applications may enter review.');const r=(await tx.query(`UPDATE vendor_applications SET status='UNDER_REVIEW',review_started_at=now(),reviewed_by_account_id=$2,updated_at=now() WHERE id=$1 RETURNING *`,[id,req.account.id])).rows[0];await statusHistory(tx,id,'SUBMITTED','UNDER_REVIEW',req.account.id,'REVIEW_STARTED');await audit(tx,{actorType:'ADMIN',actorId:req.account.id,action:'VENDOR_APPLICATION_REVIEW_STARTED',targetType:'VENDOR_APPLICATION',targetId:id});return r;});ok(res,result);}));
vendorRouter.post('/admin/vendor-applications/:applicationId/documents/:documentId/review',requireActive,review,asyncHandler(async(req,res)=>{const appId=requireUuid(req.params.applicationId),docId=requireUuid(req.params.documentId);const b=bodyObject(req.body);const status=requireEnum(b,'status',['VERIFIED','NEEDS_REPLACEMENT','REJECTED']);const reason=optionalString(b,'reason',2000)??null;const result=await transaction(async tx=>{const app=await adminApplication(appId,tx,true);if(app.status!=='UNDER_REVIEW')throw new AppError(409,'INVALID_STATE_TRANSITION','Documents are reviewable only while application is UNDER_REVIEW.');const d=await tx.query(`SELECT * FROM vendor_verification_documents WHERE id=$1 AND vendor_application_id=$2 FOR UPDATE`,[docId,appId]);if(!d.rows[0])throw new AppError(404,'VERIFICATION_DOCUMENT_NOT_FOUND','Verification document not found.');if(d.rows[0].status!=='SUBMITTED')throw new AppError(409,'INVALID_VERIFICATION_DOCUMENT_STATE','Only SUBMITTED document rows can be reviewed.');if(status!=='VERIFIED'&&!reason)throw new AppError(422,'REVIEW_REASON_REQUIRED','A non-empty reason is required for this review outcome.');const r=(await tx.query(`UPDATE vendor_verification_documents SET status=$3::verification_document_status,reviewed_by_account_id=$4,review_reason=$5,verified_at=CASE WHEN $3::verification_document_status='VERIFIED'::verification_document_status THEN now() ELSE NULL END,updated_at=now() WHERE id=$1 AND vendor_application_id=$2 RETURNING id,document_type,status,review_reason,verified_at`,[docId,appId,status,req.account.id,reason])).rows[0];await audit(tx,{actorType:'ADMIN',actorId:req.account.id,action:'VERIFICATION_DOCUMENT_REVIEWED',targetType:'VERIFICATION_DOCUMENT',targetId:docId,reason,metadata:{status}});return r;});ok(res,result);}));
async function decision(req:any,to:'NEEDS_REVISION'|'APPROVED'|'REJECTED'){const id=requireUuid(req.params.id);const b=bodyObject(req.body);const reason=optionalString(b,'reason',3000)??null;if((to==='NEEDS_REVISION'||to==='REJECTED')&&!reason)throw new AppError(400,'VALIDATION_ERROR','reason is required.');return transaction(async tx=>{const app=await adminApplication(id,tx,true);if(app.status!=='UNDER_REVIEW')throw new AppError(409,'INVALID_STATE_TRANSITION','Application must be UNDER_REVIEW.');if(to==='APPROVED'){const docs=await tx.query(`SELECT document_type,status FROM vendor_verification_documents WHERE vendor_application_id=$1`,[id]);const verified=new Set(docs.rows.filter((x:any)=>x.status==='VERIFIED').map((x:any)=>x.document_type));const need=app.vendor_type==='BUSINESS'?['KTP','VERIFICATION_SELFIE','NIB_BUSINESS_EVIDENCE']:['KTP','VERIFICATION_SELFIE'];if(need.some(x=>!verified.has(x)))throw new AppError(422,'VENDOR_APPLICATION_INCOMPLETE','Required documents are not verified.');}
 const r=(await tx.query(`UPDATE vendor_applications SET status=$2::vendor_application_status, decision_reason=$3, decided_at=CASE WHEN $2::vendor_application_status IN ('APPROVED', 'REJECTED')THEN now() ELSE NULL END, updated_at=now() WHERE id=$1 RETURNING *`,[id,to,reason])).rows[0];if(to==='APPROVED')await tx.query(`UPDATE vendors SET status='ACTIVE',approved_at=now(),suspended_at=NULL,updated_at=now() WHERE id=$1`,[app.vendor_id]);await statusHistory(tx,id,'UNDER_REVIEW',to,req.account.id,reason);await audit(tx,{actorType:'ADMIN',actorId:req.account.id,action:`VENDOR_APPLICATION_${to}`,targetType:'VENDOR_APPLICATION',targetId:id,reason});await outbox(tx,`vendor-application:${id}:${to}:${Date.now()}`,'VENDOR_APPLICATION',id,`VENDOR_APPLICATION_${to}`,{});return r;});}
vendorRouter.post('/admin/vendor-applications/:id/request-revision',requireActive,review,asyncHandler(async(req,res)=>ok(res,await decision(req,'NEEDS_REVISION'))));
vendorRouter.post('/admin/vendor-applications/:id/approve',requireActive,review,asyncHandler(async(req,res)=>ok(res,await decision(req,'APPROVED'))));
vendorRouter.post('/admin/vendor-applications/:id/reject',requireActive,review,asyncHandler(async(req,res)=>ok(res,await decision(req,'REJECTED'))));

// Authorized review access; signed URLs are short lived and never public.
vendorRouter.get('/admin/vendor-applications/:id/documents',requireActive,review,asyncHandler(async(req,res)=>{
 const id=requireUuid(req.params.id);await adminApplication(id);const r=await query<any>(`SELECT d.id,d.document_type,d.status,d.review_reason,d.created_at,m.mime_type FROM vendor_verification_documents d JOIN media_objects m ON m.id=d.media_object_id WHERE d.vendor_application_id=$1 AND m.deleted_at IS NULL ORDER BY d.created_at`,[id]);ok(res,{items:r.rows});
}));
vendorRouter.get('/admin/vendor-applications/:id/documents/:documentId/media',requireActive,review,asyncHandler(async(req,res)=>{
 const id=requireUuid(req.params.id),doc=requireUuid(req.params.documentId);const r=await query<any>(`SELECT m.object_key,m.mime_type FROM vendor_verification_documents d JOIN media_objects m ON m.id=d.media_object_id WHERE d.vendor_application_id=$1 AND d.id=$2 AND m.data_class='VERIFICATION_SENSITIVE' AND m.deleted_at IS NULL AND m.size_bytes>0`,[id,doc]);if(!r.rows[0])throw new AppError(404,'MEDIA_NOT_FOUND','Document not found.');res.setHeader('Cache-Control','no-store');ok(res,{url:signS3Url('GET',r.rows[0].object_key,120),mime_type:r.rows[0].mime_type});
}));
